let lang = "en";
try { lang = localStorage.getItem("fm-lang") || ""; } catch (_) {}
if (!STR[lang]) lang = (navigator.language || "en").slice(0, 2).toLowerCase();
if (!STR[lang]) lang = "en";

function t(key, vars) {
  let s = (STR[lang] && STR[lang][key]) || STR.en[key] || key;
  if (vars) for (const k in vars) s = s.split("{" + k + "}").join(vars[k]);
  return s;
}

// Applies static strings to elements tagged with data-i18n (text) / data-i18n-attr ("attr:key,attr:key").
function applyStaticI18n() {
  document.documentElement.lang = lang;
  document.querySelectorAll("[data-i18n]").forEach((n) => { n.textContent = t(n.dataset.i18n); });
  document.querySelectorAll("[data-i18n-attr]").forEach((n) => {
    n.dataset.i18nAttr.split(",").forEach((pair) => {
      const [attr, key] = pair.split(":");
      n.setAttribute(attr, t(key));
    });
  });
}
